import { ApolloClient, InMemoryCache, createHttpLink, ApolloLink, from } from '@apollo/client';
import { onError } from '@apollo/client/link/error';
import { setContext } from '@apollo/client/link/context';
import { RetryLink } from '@apollo/client/link/retry';
import { refreshToken } from './services/auth';

// HTTP connection to the API
const httpLink = createHttpLink({
  uri: 'http://localhost:8000/graphql',
  credentials: 'include',
});

// Middleware to add auth token to headers
const authLink = setContext((_, { headers = {} }) => {
  const token = localStorage.getItem('access_token');
  return {
    headers: {
      ...headers,
      authorization: token ? `Bearer ${token}` : '',
    },
    credentials: 'include',
  };
});

// Error handling link
const errorLink = onError(({ graphQLErrors, networkError, operation, forward }) => {
  if (graphQLErrors) {
    for (let err of graphQLErrors) {
      console.error('GraphQL Error:', err);

      // Handle token expiration or invalid token
      if (err.extensions?.code === 'UNAUTHENTICATED' || 
          err.message.includes('Not authenticated') ||
          err.message.includes('Invalid token') ||
          err.message.includes('Token expired')) {

        // Avoid refresh token loop
        if (operation.operationName === 'RefreshToken') {
          console.log('Refresh token request failed, redirecting to login');
          clearAuthAndRedirect();
          return;
        }

        const refreshTokenValue = localStorage.getItem('refresh_token');
        if (refreshTokenValue) {
          console.log('Attempting to refresh access token...');
          return refreshToken()
            .then(({ access_token, refresh_token }) => {
              if (!access_token) {
                throw new Error('No access token in refresh response');
              }

              console.log('Token refreshed successfully');
              localStorage.setItem('access_token', access_token);
              if (refresh_token) {
                localStorage.setItem('refresh_token', refresh_token);
              }

              // Safely handle operation context
              const operationContext = typeof operation.getContext === 'function' ? operation.getContext() : {};
              const oldHeaders = operationContext.headers || {};

              // Create new context with updated token
              const context = {
                ...operationContext,
                headers: {
                  ...oldHeaders,
                  authorization: `Bearer ${access_token}`,
                },
              };

              // Create new operation with updated context
              const newOperation = {
                ...operation,
                setContext: (newContext) => {
                  Object.assign(context, newContext);
                },
                getContext: () => context,
              };

              return forward(newOperation);
            })
            .catch(error => {
              console.error('Failed to refresh token:', error);
              clearAuthAndRedirect();
            });
        } else {
          console.log('No refresh token available, redirecting to login');
          clearAuthAndRedirect();
        }
      }
    }
  }

  if (networkError) {
    console.error('Network Error:', networkError);
  }
});

// Helper function to clear auth and redirect to login
function clearAuthAndRedirect() {
  localStorage.removeItem('access_token');
  localStorage.removeItem('refresh_token');
  if (window.location.pathname !== '/login') {
    window.location.href = '/login';
  }
}

// Rate limiting middleware
const rateLimitLink = new ApolloLink((operation, forward) => {
  // Skip rate limiting for certain operations
  if (operation.operationName === 'RefreshToken') {
    return forward(operation);
  }

  return forward(operation);
});

// Retry link with exponential backoff
const retryLink = new RetryLink({
  delay: {
    initial: 300,
    max: Infinity,
    jitter: true
  },
  attempts: (count, operation, error) => {
    if (error?.networkError) {
      console.warn(`Retry attempt ${count} for operation ${operation.operationName} due to network error.`);
      return true; // Retry network errors
    }

    if (error?.graphQLErrors) {
      for (let err of error.graphQLErrors) {
        // Don't retry on authentication or validation errors
        if (err.extensions?.code === 'UNAUTHENTICATED' || 
            err.extensions?.code === 'BAD_USER_INPUT') {
          console.error(`Not retrying operation ${operation.operationName} due to GraphQL error: ${err.message}`);
          return false;
        }
      }
    }

    return count < 3; // Retry up to 3 times for other errors
  }
});

// Create the Apollo Client instance
const client = new ApolloClient({
  link: from([
    errorLink,
    authLink,
    rateLimitLink,
    retryLink,
    httpLink
  ]),
  cache: new InMemoryCache({
    typePolicies: {
      Query: {
        fields: {
          messages: {
            keyArgs: ['type'],
            merge(existing, incoming, { args: { offset = 0 } }) {
              const merged = existing ? existing.slice(0) : [];
              for (let i = 0; i < incoming.length; ++i) {
                merged[offset + i] = incoming[i];
              }
              return merged;
            },
          },
        },
      },
    },
  }),
  defaultOptions: {
    watchQuery: {
      fetchPolicy: 'cache-and-network',
      errorPolicy: 'all',
    },
    query: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    mutate: {
      errorPolicy: 'all',
    },
  },
});

export default client;
